/// Extract low 128 bits and high 126 bits from a BN254 field element,
/// reverse the high 126 bits, and combine as: low + 2*reversed_high.
/// Matches ExtractAndCombine (Num2Bits_strict) in circuits/polynomial_hash.circom.
/// Not injective (254→<129 bits); poly-hash collision resistance is via coeffs.
export function bn254ExtractAndCombine(value: bigint): bigint {
  const low = value & ((1n << 128n) - 1n);
  const high = (value >> 128n) & ((1n << 126n) - 1n);

  let reversed = 0n;
  for (let i = 0; i < 126; i++) {
    if ((high >> BigInt(i)) & 1n) {
      reversed |= 1n << BigInt(125 - i);
    }
  }

  return low + 2n * reversed;
}

/// Compute the polynomial hash of 900 pre-extracted values.
/// Matches the PolynomialHash template in circuits/polynomial_hash.circom.
///
/// When `nActualPlayers` is set (2..=10), only recipient rows
/// `i < nActualPlayers-1` and cards in `{0..2n-1} ∪ {20..24}` contribute
/// (absolute HASH_COEFFS indices preserved). Matches poker_polynomial_hash.circom.
///
/// SAFETY: Max result < 900 * 2^229 < 2^239 < BN254 prime and Ed25519 prime.
/// No wraparound in either field.
export function hash900Values(values: bigint[], nActualPlayers?: number): bigint {
  if (values.length !== 900) {
    throw new Error(`Expected 900 values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 900; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 10) {
    throw new Error(`nActualPlayers must be 2..10, got ${nActualPlayers}`);
  }

  const nOthers = 9;
  const nCards = 25;
  const boardStart = 20;
  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      const cardActive = j >= boardStart || j < 2 * nActualPlayers;
      const active = recipientActive && cardActive;
      for (let k = 0; k < 4; k++) {
        if (active) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

/// Compute the polynomial hash of 900 BN254 field elements.
/// Applies bn254ExtractAndCombine to each value before hashing.
/// Convenience wrapper for share partials and deck hashing.
export function hash900Bn254(values: bigint[], nActualPlayers?: number): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash900Values(extracted, nActualPlayers);
}

/** Interpret a 32-byte commitment as a 256-bit big-endian integer. */
export function commitmentToBigInt(commitment: Uint8Array): bigint {
  let val = 0n;
  let mul = 1n;
  for (let j = 31; j >= 0; j--) {
    val += BigInt(commitment[j]!) * mul;
    mul *= 256n;
  }
  return val;
}

/** Circom / Arcis ExtractAndCombine on a big-endian BN254 commitment. */
export function extractAndCombineCommitment(commitment: Uint8Array): bigint {
  return bn254ExtractAndCombine(commitmentToBigInt(commitment));
}

/**
 * Polynomial hash of 900 BN254 commitments (card-major staging layout).
 *
 * When `nActualPlayers` is set, for each active card takes the first
 * `(nActualPlayers - 1) * 4` limbs at `card * 36 + j` (reveal/staging path).
 * Differs from recipient-major `hash900Values` sparse indexing.
 */
export function hashDeck900(
  commitments: Uint8Array[],
  nActualPlayers?: number,
): bigint {
  if (commitments.length !== 900) {
    throw new Error(`Expected 900 commitments, got ${commitments.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 900; i++) {
      hash += extractAndCombineCommitment(commitments[i]!) * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 10) {
    throw new Error(`nActualPlayers must be 2..10, got ${nActualPlayers}`);
  }

  const limbCount = (nActualPlayers - 1) * 4;
  const boardStart = 20;
  for (let card = 0; card < 25; card++) {
    const cardActive = card >= boardStart || card < 2 * nActualPlayers;
    if (!cardActive) continue;
    const base = card * 36;
    for (let j = 0; j < limbCount; j++) {
      const idx = base + j;
      hash += extractAndCombineCommitment(commitments[idx]!) * HASH_COEFFS_900[idx]!;
    }
  }
  return hash;
}

/** Baccarat share: 11 recipients × 6 cards × 4 limbs. Optional active-recipient mask. */
export function hash264Values(values: bigint[], nActualPlayers?: number): bigint {
  if (values.length !== 264) {
    throw new Error(`Expected 264 values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 264; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 12) {
    throw new Error(`nActualPlayers must be 2..12, got ${nActualPlayers}`);
  }

  const nOthers = 11;
  const nCards = 6;
  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      for (let k = 0; k < 4; k++) {
        if (recipientActive) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

export function hash264Bn254(values: bigint[], nActualPlayers?: number): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash264Values(extracted, nActualPlayers);
}

/** War share: 11 recipients × 4 cards × 4 limbs. Optional active-recipient mask. */
export function hash176Values(values: bigint[], nActualPlayers?: number): bigint {
  if (values.length !== 176) {
    throw new Error(`Expected 176 values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 176; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 12) {
    throw new Error(`nActualPlayers must be 2..12, got ${nActualPlayers}`);
  }

  const nOthers = 11;
  const nCards = 4;
  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      for (let k = 0; k < 4; k++) {
        if (recipientActive) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

export function hash176Bn254(values: bigint[], nActualPlayers?: number): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash176Values(extracted, nActualPlayers);
}

/** Blackjack share chunk: 7 recipients × 16 cards × 4 limbs. Optional active-recipient mask. */
export function hash448Values(values: bigint[], nActualPlayers?: number): bigint {
  if (values.length !== 448) {
    throw new Error(`Expected 448 values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 448; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 8) {
    throw new Error(`nActualPlayers must be 2..8, got ${nActualPlayers}`);
  }

  const nOthers = 7;
  const nCards = 16;
  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      for (let k = 0; k < 4; k++) {
        if (recipientActive) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

export function hash448Bn254(values: bigint[], nActualPlayers?: number): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash448Values(extracted, nActualPlayers);
}

/** Roulette share: 11 recipients × 1 card × 4 limbs. Optional active-recipient mask. */
export function hash44Values(values: bigint[], nActualPlayers?: number): bigint {
  if (values.length !== 44) {
    throw new Error(`Expected 44 values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < 44; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > 12) {
    throw new Error(`nActualPlayers must be 2..12, got ${nActualPlayers}`);
  }

  const nOthers = 11;
  const nCards = 1;
  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      for (let k = 0; k < 4; k++) {
        if (recipientActive) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

export function hash44Bn254(values: bigint[], nActualPlayers?: number): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash44Values(extracted, nActualPlayers);
}

/** Recipient-major poly hash: `nOthers × nCards × 4` limbs, optional active-recipient mask. */
function hashRecipientMajorValues(
  expected: number,
  nOthers: number,
  nCards: number,
  maxActualPlayers: number,
  values: bigint[],
  nActualPlayers?: number,
): bigint {
  if (values.length !== expected) {
    throw new Error(`Expected ${expected} values, got ${values.length}`);
  }

  let hash = 0n;
  if (nActualPlayers == null) {
    for (let i = 0; i < expected; i++) {
      hash += values[i]! * HASH_COEFFS_900[i]!;
    }
    return hash;
  }

  if (nActualPlayers < 2 || nActualPlayers > maxActualPlayers) {
    throw new Error(`nActualPlayers must be 2..${maxActualPlayers}, got ${nActualPlayers}`);
  }

  let idx = 0;
  for (let i = 0; i < nOthers; i++) {
    const recipientActive = i < nActualPlayers - 1;
    for (let j = 0; j < nCards; j++) {
      for (let k = 0; k < 4; k++) {
        if (recipientActive) {
          hash += values[idx]! * HASH_COEFFS_900[idx]!;
        }
        idx++;
      }
    }
  }
  return hash;
}

function hashRecipientMajorBn254(
  expected: number,
  nOthers: number,
  nCards: number,
  maxActualPlayers: number,
  values: bigint[],
  nActualPlayers?: number,
): bigint {
  return hashRecipientMajorValues(
    expected,
    nOthers,
    nCards,
    maxActualPlayers,
    values.map(v => bn254ExtractAndCombine(v)),
    nActualPlayers,
  );
}

/** Craps share: 11 recipients × 2 dice × 4 limbs. */
export function hash88Values(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorValues(88, 11, 2, 12, values, nActualPlayers);
}

export function hash88Bn254(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorBn254(88, 11, 2, 12, values, nActualPlayers);
}

/** Keno share: 11 recipients × 20 numbers × 4 limbs. */
export function hash880Values(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorValues(880, 11, 20, 12, values, nActualPlayers);
}

export function hash880Bn254(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorBn254(880, 11, 20, 12, values, nActualPlayers);
}

/** Bingo share chunk: 11 recipients × 5 balls × 4 limbs. */
export function hash220Values(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorValues(220, 11, 5, 12, values, nActualPlayers);
}

export function hash220Bn254(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorBn254(220, 11, 5, 12, values, nActualPlayers);
}

/** 3-reel slots share: 1 recipient × 3 stops × 4 limbs. */
export function hash12Values(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorValues(12, 1, 3, 2, values, nActualPlayers);
}

export function hash12Bn254(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorBn254(12, 1, 3, 2, values, nActualPlayers);
}

/** 5-reel slots share: 1 recipient × 5 stops × 4 limbs. */
export function hash20Values(values: bigint[], nActualPlayers?: number): bigint {
  return hashRecipientMajorValues(20, 1, 5, 2, values, nActualPlayers);
}

