/// SAFETY: 8120 terms × max(extracted ~2^129) × max(coeff ~2^100) < 2^242 < BN254 and Ed25519 primes.
export function hash8120Values(values: bigint[]): bigint {
  if (values.length !== 8120) throw new Error(`Expected 8120 values, got ${values.length}`);
  let hash = 0n;
  for (let i = 0; i < 8120; i++) hash += values[i]! * HASH_COEFFS_8120[i]!;
  return hash;
}

export function hash8120Bn254(values: bigint[]): bigint {
  const extracted = values.map(v => bn254ExtractAndCombine(v));
  return hash8120Values(extracted);
}
